package com.careflow.hospital.doctors;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="doctor_application")
public class DoctorApplication {@Id @Column(name="application_id")private UUID id;@Column(name="user_id",nullable=false,unique=true)private UUID userId;@Column(name="full_name",nullable=false)private String fullName;@Column(nullable=false)private String specialization;@Column(name="department_id",nullable=false)private UUID departmentId;@Column(nullable=false)private String qualifications;@Column(name="experience_years",nullable=false)private int experienceYears;@Column(name="license_number",nullable=false,unique=true)private String licenseNumber;@Column(nullable=false)private String status;@Column(name="reviewed_by")private UUID reviewedBy;@Column(name="reviewed_at")private Instant reviewedAt;@Column(name="created_at",nullable=false)private Instant createdAt;
 protected DoctorApplication(){}public DoctorApplication(UUID userId,String name,String specialty,UUID departmentId,String qualifications,int years,String license){this.id=UUID.randomUUID();this.userId=userId;this.fullName=name;this.specialization=specialty;this.departmentId=departmentId;this.qualifications=qualifications;this.experienceYears=years;this.licenseNumber=license;this.status="PENDING";this.createdAt=Instant.now();}
 public UUID getId(){return id;}public UUID getUserId(){return userId;}public String getFullName(){return fullName;}public String getSpecialization(){return specialization;}public UUID getDepartmentId(){return departmentId;}public String getQualifications(){return qualifications;}public int getExperienceYears(){return experienceYears;}public String getLicenseNumber(){return licenseNumber;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}
 public void approve(UUID admin){requirePending();status="APPROVED";reviewedBy=admin;reviewedAt=Instant.now();}public void reject(UUID admin){requirePending();status="REJECTED";reviewedBy=admin;reviewedAt=Instant.now();}private void requirePending(){if(!"PENDING".equals(status))throw new IllegalStateException("Application was already reviewed");}}
